export const REMOCN_COMPONENT_IDS = new Set(REMOCN_COMPONENTS.map((c) => c.id));

export function getRemocnComponent(id: string): RemocnComponentMeta | undefined {
  return REMOCN_COMPONENTS.find((c) => c.id === id);
}

/** Lazily import a remocn component module by id; resolves to the module's exports. */
export function loadRemocnComponent(id: string): Promise<Record<string, unknown>> {
  const load = loaders[id];
  if (!load) return Promise.reject(new Error(`Unknown remocn component: ${id}`));
  return load();
}
